<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:11px;color:#1f2937}h1{font-size:20px}h2{font-size:14px;margin:18px 0 6px}.meta{color:#4b5563}.record{border-top:1px solid #d1d5db;padding:12px 0}.label{font-weight:bold}</style></head><body><h1>Histórico clínico</h1><p><strong>{{ $patient->name }}</strong><br><span class="meta">Documento: {{ $patient->document }} · Nascimento: {{ $patient->birth_date->format('d/m/Y') }}</span></p>@forelse($patient->clinicalRecords as $record)<article class="record"><h2>{{ $record->type === 'initial_assessment' ? 'Avaliação inicial' : 'Evolução' }} · {{ $record->performed_at->format('d/m/Y') }}</h2><p class="meta">Profissional: {{ $record->professional->name }} · Dor: {{ $record->pain_level ?? '—' }}/10</p><p><span class="label">Queixa/relato:</span> {{ $record->complaint }}</p><p><span class="label">Avaliação:</span> {{ $record->physical_assessment }}</p><p><span class="label">Conduta:</span> {{ $record->conduct }}</p><p><span class="label">Próximos passos:</span> {{ $record->next_steps }}</p></article>@empty<p>Nenhum registro clínico cadastrado.</p>@endforelse</body></html>
